// Storage the auth module needs. Every method maps to one or two SQL statements against the tables in
// schema.sql, so a `pg` implementation is a thin layer. Emails are always passed normalized (trimmed,
// lowercased); ids are generated by the caller.

export type Role = "owner" | "member";

export interface UserRecord {
  id: string;
  /** Lowercased. Unique. */
  email: string;
  name: string | null;
  /** `scrypt$...` (see password.ts), or null for users who only sign in with OIDC. */
  password_hash: string | null;
  created_at: Date;
}

export interface IdentityRecord {
  issuer: string;
  subject: string;
  user_id: string;
  /** Email the provider reported at link time, for display and auditing only (never used to match). */
  email: string | null;
  created_at: Date;
}

export interface SessionRecord {
  /** Hex SHA-256 of the cookie token. The token itself is never stored. */
  token_hash: string;
  user_id: string;
  created_at: Date;
  expires_at: Date;
  /** When expires_at was last pushed forward. */
  renewed_at: Date;
}

export interface AuthStore {
  countUsers(): Promise<number>;
  getUserById(id: string): Promise<UserRecord | null>;
  getUserByEmail(email: string): Promise<UserRecord | null>;
  /**
   * Inserts a user, and the identity in the same transaction when given. Throws EmailTakenError if the
   * email is in use (unique violation 23505 on users.email) and IdentityTakenError if (issuer, subject)
   * is already linked.
   */
  createUser(user: UserRecord, identity?: IdentityRecord): Promise<void>;
  setPasswordHash(userId: string, hash: string | null): Promise<void>;

  /** The user linked to this OIDC identity, or null. */
  findUserByIdentity(issuer: string, subject: string): Promise<UserRecord | null>;
  /** Links an identity to an existing user. Throws IdentityTakenError if already linked. */
  addIdentity(identity: IdentityRecord): Promise<void>;

  createSession(session: SessionRecord): Promise<void>;
  /** The session and its user (one JOIN), or null. Returns expired sessions too; the caller checks. */
  getSession(tokenHash: string): Promise<{ session: SessionRecord; user: UserRecord } | null>;
  /** Sliding renewal: sets expires_at and renewed_at. */
  renewSession(tokenHash: string, expiresAt: Date, renewedAt: Date): Promise<void>;
  deleteSession(tokenHash: string): Promise<void>;
  /** Signs a user out everywhere (used when their password changes). */
  deleteUserSessions(userId: string): Promise<void>;
  /** Housekeeping; returns how many were removed. */
  deleteExpiredSessions(now: Date): Promise<number>;

  /** The user's role in the workspace, or null if not a member (or no such workspace). */
  getMembership(workspaceId: string, userId: string): Promise<Role | null>;
}

export class EmailTakenError extends Error {
  constructor() {
    super("email already in use");
  }
}

export class IdentityTakenError extends Error {
  constructor() {
    super("identity already linked");
  }
}
